SELECT 'batch_001_3d159900_wav_12' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-004b6062-e62','sm-upload-0eebf238-f29','sm-upload-15e574ee-8ae','sm-upload-1e608bde-aeb','sm-upload-39152c54-b80','sm-upload-43974d21-5b5','sm-upload-43a886a9-559','sm-upload-9bfc667e-5ef','sm-upload-bb441daa-4a0','sm-upload-dbc1d60c-3c2','sm-upload-e18930ac-8e1','sm-upload-ed4828e7-cf9') AND album_id='al-8722d4ca7293612ea92d2f283d159900') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-004b6062-e62','sm-upload-0eebf238-f29','sm-upload-15e574ee-8ae','sm-upload-1e608bde-aeb','sm-upload-39152c54-b80','sm-upload-43974d21-5b5','sm-upload-43a886a9-559','sm-upload-9bfc667e-5ef','sm-upload-bb441daa-4a0','sm-upload-dbc1d60c-3c2','sm-upload-e18930ac-8e1','sm-upload-ed4828e7-cf9') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-8722d4ca7293612ea92d2f283d159900' AND name='星座-扑克') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-8722d4ca7293612ea92d2f283d159900') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-8722d4ca7293612ea92d2f283d159900') AS calculated_size;
